return {role02001={id="role02001",baseId="npc02001",combatid={1,2034},name="真荣",teamMark=-1,canSee=1,caozuoName1="劝说",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL真荣：住口！你这目光短浅之人，我所做之事全是为了重光教无上的荣耀！NOR"}}},caozuoName2="擒拿",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="challenge",args={"role02001"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="challengewin",args={"role02001"}}}},autoResult1={{type="doc",args={"CYN真荣本就负伤，抵抗了你几招后，趁你不备转身向山顶逃去。NOR"}},{type="gaintab",args={"20001",9}},{type="change",args={"role02001","item29"}}},autoCondition2={relation="and",conditions={{type="challengelose",args={"role02001"}}}},autoResult2={{type="doc",args={"YEL真荣：哼！就凭你也想带我回去？真是白日做梦！NOR"}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},role02002={id="role02002",baseId="npc02006",combatid={1,2040},name="神秘高手",teamMark=-1,canSee=1,caozuoName1="对峙",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL神秘高手：哼！我奉瓦尔塔大人之命清理掉所有进入迷林之人，你还是乖乖受死吧！NOR"}}},caozuoName2="决斗",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="challenge",args={"role02002"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="challengewin",args={"role02002"}}}},autoResult1={{type="doc",args={"CYN神秘高手见不敌于你，便使出阴招，在你招架躲避之时转身而逃，消失的无影无踪。NOR"}},{type="gaintab",args={"20005",2}},{type="gaintab",args={"20004",1}},{type="outobject",args={"role02002"}},{type="addobject",args={"item11"}}},autoCondition2={relation="and",conditions={{type="challengelose",args={"role02002"}}}},autoResult2={{type="doc",args={"YEL神秘高手：就你这点实力还学别人行侠仗义？真是可笑！NOR"}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"20005",0}},{type="equaltab",args={"20004",0}},{type="inroom",args={"any","room0211"}}}},autoResult3={{type="gaintab",args={"20005",1}}},autoCondition4={relation="and",conditions={{type="equaltab",args={"20005",1}},{type="inroom",args={"room0211","any"}}}},autoResult4={{type="stop",args={}},{type="doc",args={"CYN神秘高手紧盯着你，看样子无法饶过他离开。NOR"}}},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},role02003={id="role02003",baseId="npc02007",combatid={1,2016},name="脏老头",teamMark=-1,canSee=1,caozuoName1="观察",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL脏老头看似五六十岁，花白的头发蓬乱不堪，其中还夹杂着一些枝叶，衣服上全是泥土，袖口处还有一些干涸的血迹。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"CYN脏老头未回答你的问题，而是转身走到旁边不起眼的石堆边，俯身在石堆中捣鼓一番后才告诉你那石堆中设有机关，现已被他拆除了。NOR"}},{type="gaintab",args={"20008",3}},{type="deletetab",args={"20010"}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}},{type="refresh",args={}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL脏老头：唉，少侠你有所不知，我们本是凉州的匠人，被这伙贼人瞒骗到山中，被逼在山中修筑各种机关暗器。"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL脏老头：这伙贼人阴毒的很，他们圈养了一群恶狼，一旦有人反抗逃跑被他们抓住，就会丢给恶狼生吞活剥！"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL脏老头：不久前他们大举撤离，还将被抓来的匠人赶尽杀绝。我熟悉山中的地形和机关，想趁乱逃出去，没想到还是被抓，多亏少侠出手相救，不然我今日就命丧于此了。NOR"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"20008",2}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},role02004={id="role02004",baseId="npc02008",combatid={1,2035},name="蒙面人",teamMark=-1,canSee=1,caozuoName1="观察",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL脏老头：你…你们这些阴险狡诈的无耻之徒，老夫就是做鬼也不会放过你们的！"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL蒙面人：嚯哟！格老子滴，老子长这么球大啷个没见过鬼喃，莫给老子废话，今天你龟儿长了翅膀也要死的邦硬！"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL蒙面人：莫要跟老子乱叫，你也莫要怪我，要怪就怪你们知道的太多喽！不然又怎会落到介过下场！NOR"}}},caozuoName2="出手救人",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="challenge",args={"role02004"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="challengewin",args={"role02004"}}}},autoResult1={{type="doc",args={"CYN就在蒙面人向脏老头出手之际，你出手相救，与蒙面人交战数个回合，蒙面人见不敌于你便逃往山下，转眼就消失不见。NOR"}},{type="gaintab",args={"20008",2}},{type="outobject",args={"role02004"}},{type="refresh",args={}}},autoCondition2={relation="and",conditions={{type="challengelose",args={"role02004"}}}},autoResult2={{type="doc",args={"YEL蒙面人：奏你介过样子，还想救人？真是笑死老子。NOR"}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},role02005={id="role02005",baseId="npc02007",combatid={1,2016},name="脏老头",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL脏老头：少侠，这迷山本就凶险，更何况还被设下了重重机关。"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL脏老头：那些机关多数出自老夫之手，如何躲避、如何拆解老夫都了如指掌，还请让老夫与少侠同行，助少侠一臂之力，也好报答少侠的救命之恩。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL脏老头：若想下山用这机关是最快也是最安全的，不过前提是要将它修复一下，不然也是凶多吉少。"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL脏老头：沿着兽道过去能进到林子里，只需要一些藤条和硬木，老夫就可以将这机关修复。NOR"}},{type="refresh",args={}}},caozuoName3="询问",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL脏老头：唉，方才太过混乱，我在取修机关材料时手受伤了，操作不便，你拿着这些材料，老夫教你如何修复，你只管按照我所说的弄就行。NOR"}},{type="gaintab",args={"20009",4}},{type="refresh",args={}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL脏老头：好了，这滑索已经可以使用了。NOR"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"20009",1}},{type="inroom",args={"room0201","room0204"}}}},autoResult1={{type="objectmove",args={"role02005","room0204"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="gaintab",args={"20009",2}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"20009",3}}}},autoResult2={{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"20009",5}}}},autoResult3={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},role02006={id="role02006",baseId="npc02009",combatid={1,2037},name="训狼人",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL训狼人：方才听闻说山中来了个武功高强的人捣乱，想必说的就是你吧？"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL训狼人：你武功如何我不清楚，但你能见到我只能说明你运气不好。NOR"}}},caozuoName2="决斗",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="challenge",args={"role02006"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="challengewin",args={"role02006"}}}},autoResult1={{type="doc",args={"CYN你虽武功高强，但训狼人武功亦不低，两匹黑狼也凶狠非常，你们僵持不下之际，闻声而来的老者扔出一枚暗器打乱了训狼人的攻击，你抓住机会将训狼人击杀，而两匹黑狼蹿回了林中，随后传来了阵阵狼嚎。NOR"}},{type="gaintab",args={"20009",3}},{type="change",args={"role02006","item55"}},{type="outobject",args={"role02007"}},{type="outobject",args={"role02008"}},{type="change",args={"item36","item39"}},{type="addobject",args={"role02009"}},{type="refresh",args={}}},autoCondition2={rel