ons={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},role02009={id="role02009",baseId="npc02007",combatid={1,2016},name="脏老头",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL脏老头：狼群正在往这边赶，那群畜牲怕是要发疯了。少侠快拉那边的绳子！"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL脏老头：绳子是我之前留下的机关，拉动它可以封住兽道！NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},role02010={id="role02010",baseId="npc02007",combatid={1,2016},name="脏老头",teamMark=-1,canSee=1,caozuoName1="询问",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL脏老头：此处设有机关，若不拆除定会触发，少侠稍等片刻，老夫有办法将其解除。NOR"}},{type="delayer",args={3,"少侠，稍安勿躁"}},{type="doc",args={"CYN只见他再滑索上捣鼓了一阵，拆了一个精巧的机关。NOR"}},{type="gaintab",args={"20009",7}},{type="addobject",args={"item40"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL脏老头：机关已经解除了，可以继续前行了。NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="unequaltab",args={"20010",0}}}},autoResult1={{type="outobject",args={"role02010"}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},role02011={id="role02011",baseId="npc02007",combatid={1,2016},name="脏老头",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL脏老头：前面就是怒江了，我在江边藏了船，乘船离开要快得多。不过这伙贼人也往江边去，要小心着些。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL脏老头：这里左临江水，右靠山崖，若不将他们击到，我们无法过去。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL脏老头：好身手，我们快过去吧。NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL脏老头：少侠小心，这家伙非常厉害，我曾见过他与别人动手，招招狠毒难防。NOR"}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL脏老头：哼！死的好！已经不知有多少人死在他的手上，今日也算为民除害了。NOR"}}},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"20009",8}},{type="inroom",args={"room0217","room0216"}}}},autoResult1={{type="objectmove",args={"role02011","room0216"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"20009",10}}}},autoResult2={{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"20009",10}},{type="inroom",args={"room0216","room0215"}}}},autoResult3={{type="objectmove",args={"role02011","room0215"}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}},{type="gaintab",args={"20009",11}}},autoCondition4={relation="and",conditions={{type="equaltab",args={"20009",12}}}},autoResult4={{type="showbutton",args={4,0}},{type="showbutton",args={5,1}}},autoCondition5={relation="and",conditions={{type="tabgr",args={"20009",13}}}},autoResult5={{type="outobject",args={"role02011"}}},autoCondition6={relation="and",conditions={}},autoResult6={}},role02012={id="role02012",baseId="npc02012",combatid={1,2039},name="黑衣人",teamMark=-1,canSee=1,caozuoName1="观察",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL黑衣人：你们说这黑狼肉是什么味道的？"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"黑衣人：你真敢问啊，小心被狼头子听到，将你去喂狼。"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"黑衣人：你们俩闭嘴，有人过来了。NOR"}}},caozuoName2="决斗",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="challenge",args={"role02012"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},b